  newest: 'r.created_at DESC',
  oldest: 'r.created_at ASC',
  rating: 'r.rating DESC, r.created_at DESC',
};

// Reviews for a book in one of the whitelisted orders.
export function getReviewsSorted(bookId: number, sortKey: string): ReviewWithDetails[] {
